export function countComponents(n        , edges            )         {
const adj           =Array.from({length:n},()=>[]);for(const [a,b] of edges){adj[a].push(b);adj[b].push(a);}const seen=new Set        ();let count=0;for(let i=0;i<n;i++)if(!seen.has(i)){count++;seen.add(i);const stack=[i];while(stack.length){const x=stack.pop() ;for(const y of adj[x])if(!seen.has(y)){seen.add(y);stack.push(y);}}}return count;
}

